// Generated by build.mjs from the reviewed question context changes.
export const QUESTION_REVISIONS = [{"id":17,"beforeQuestionRo":"O echipă solicită o înlocuire. Înainte ca înlocuitorul să intre pe teren, un alt jucător al aceleiași echipe se accidentează grav. Poate echipa să schimbe înlocuirea solicitată?","afterQuestionRo":"Antrenorul echipei A anunță un oficial că va introduce un atacant ca ultim înlocuitor disponibil. Acesta așteaptă la linia mediană și nu a intrat încă. Arbitrul oprește jocul după ce un apărător al echipei A este faultat și se accidentează grav. Poate echipa să își schimbe decizia și să folosească un alt înlocuitor?","correctText":"Da; înlocuirea nu este finalizată până când înlocuitorul intră pe teren."},{"id":30,"beforeQuestionRo":"Un apărător accidentat, aflat în spatele liniei porții, reintră fără permisiune și degajează din propria suprafață de pedeapsă mingea care intra în poartă. Care este decizia arbitrului?","afterQuestionRo":"Un apărător al echipei A a părăsit terenul pentru îngrijiri după o accidentare ușoară și se află încă în spatele liniei propriei porți. Un atacant al echipei B șutează pe lângă portarul echipei A, iar mingea se îndreaptă spre poarta acesteia. Apărătorul reintră fără permisiunea arbitrului și degajează mingea din propria suprafață de pedeapsă, împiedicând-o să intre în poartă. Care este decizia arbitrului?","correctText":"LP și CR pentru reintrare neautorizată și intervenție."},{"id":90,"beforeQuestionRo":"După un fault, arbitrul întârzie reluarea pentru evaluarea jucătorului accidentat. Când poate acesta rămâne pe teren și executa lovitura liberă?","afterQuestionRo":"Arbitrul oprește jocul și acordă o lovitură liberă pentru un fault asupra unui jucător al echipei A. Întârzie reluarea pentru ca personalul medical să îl evalueze pe teren. În ce condiții poate jucătorul rămâne pe teren, dacă poate continua după evaluarea sau îngrijirile inițiale?","correctText":"Dacă adversarul primește CG sau CR pentru abaterea fizică."},{"id":121,"beforeQuestionRo":"Un jucător este accidentat în urma unui atac imprudent sancționat cu CG. Arbitrul autorizează intrarea brancardierilor, dar jucătorul refuză să părăsească terenul. Cum procedează arbitrul?","afterQuestionRo":"Un jucător este accidentat în urma unui atac imprudent pentru care adversarul primește CG. După evaluarea sau îngrijirile inițiale pe teren, personalul medical stabilește că jucătorul nu mai trebuie să continue jocul. Arbitrul autorizează intrarea brancardierilor, dar jucătorul refuză să părăsească terenul. Cum procedează arbitrul?","correctText":"Jucătorul primește CG și trebuie să părăsească terenul pe targă sau pe jos."},{"id":128,"beforeQuestionRo":"AA semnalizează o lovire comisă de un apărător în propria suprafață de pedeapsă, dar arbitrul vede semnalul abia după reluarea jocului cu aruncare de la margine. Ce poate decide?","afterQuestionRo":"Cu mingea în joc, un apărător lovește un atacant în propria suprafață de pedeapsă. Arbitrul asistent semnalizează abaterea, dar arbitrul nu observă semnalul. Jocul continuă, mingea iese din teren, iar jocul este reluat cu o aruncare de la margine înainte ca arbitrul să afle de incident. Ce poate decide arbitrul?","correctText":"Nu poate acorda LP, dar poate arăta CR apărătorului vinovat."},{"id":217,"beforeQuestionRo":"Mingea șutată de un atacant al echipei A iese clar spre lovitură de poartă. Înainte să iasă, un jucător înlocuitor al echipei B o oprește cu piciorul pe linia porții, fără a intenționa să intervină în joc. Care este decizia arbitrului?","afterQuestionRo":"Un atacant al echipei A șutează la câțiva metri pe lângă poartă. Mingea se îndreaptă clar în afara terenului pentru o lovitură de poartă și niciun jucător nu mai are șansa să o atingă înainte de ieșire. Un înlocuitor al echipei B, care se încălzește lângă linia porții, o oprește cu piciorul chiar pe linie, fără a intenționa să intervină în joc. Care este decizia arbitrului?","correctText":"Lovitură liberă indirectă pentru A, fără sancțiune disciplinară."},{"id":284,"beforeQuestionRo":"La o lovitură liberă, un apărător ține în suprafața de pedeapsă un atacant înainte ca mingea să ajungă la alt atacant aflat în ofsaid, care înscrie. Care este decizia tehnică?","afterQuestionRo":"La o lovitură liberă, mingea este trimisă în suprafața de pedeapsă adversă. Cât timp mingea este în aer, un apărător ține un atacant și îl împiedică să sară pentru a o juca. Mingea ajunge apoi la un alt atacant, aflat în poziție de ofsaid la executarea loviturii, care înscrie. Care este decizia tehnică a arbitrului?","correctText":"Gol anulat; LP acordată echipei în atac."},{"id":335,"beforeQuestionRo":"Un apărător atinge accidental mingea cu brațul aflat într-o poziție care mărește nenatural corpul, în propria suprafață de pedeapsă. Mingea ajunge la alt atacant, care înscrie. Care este decizia arbitrului?","afterQuestionRo":"Un atacant șutează spre poarta goală. În propria suprafață de pedeapsă, un apărător încearcă să blocheze șutul și atinge accidental mingea cu mâna sau brațul, aflat într-o poziție care îi mărește în mod nenatural suprafața corpului. Mingea își schimbă direcția și ajunge la un alt atacant, care înscrie. Care este decizia arbitrului?","correctText":"Avantaj, gol acordat și nicio sancțiune."},{"id":340,"beforeQuestionRo":"Un atacant trece de portar în suprafața de pedeapsă. Portarul îl faultează din neglijență, împiedicând o ocazie clară de gol (DOGSO), dar mingea intră totuși direct în poartă. Care este decizia arbitrului?","afterQuestionRo":"Un atacant conduce mingea în suprafața de pedeapsă adversă și încearcă să treacă de portar, având o ocazie clară de gol. Portarul încearcă să joace mingea, dar îl faultează din neglijență. Atacantul cade, însă mingea intră direct în poarta portarului. Care este decizia arbitrului?","correctText":"Gol acordat, fără CG sau CR pentru portar."},{"id":342,"beforeQuestionRo":"Un apărător joacă deliberat mingea cu mâna în afara propriei suprafețe de pedeapsă și comite DOGSO. Arbitrul aplică avantajul, iar un alt atacant preia mingea și înscrie. Care este decizia arbitrului?","afterQuestionRo":"În afara propriei suprafețe de pedeapsă, un apărător al echipei A oprește deliberat cu mâna sau brațul o pasă spre un atacant al echipei B, împiedicând o ocazie clară de gol. Un alt jucător al echipei B preia însă mingea, aleargă singur spre portar și înscrie, arbitrul lăsând jocul să continue. Care este decizia arbitrului?","correctText":"Gol acordat, fără CG sau CR pentru apărător."},{"id":356,"beforeQuestionRo":"Un atacant sare fără contact în fața portarului care aruncă mingea; aceasta îi ricoșează din cap în poartă. Care este decizia arbitrului?","afterQuestionRo":"Portarul prinde mingea în propria suprafață de pedeapsă. Un atacant advers se apropie foarte mult și, în timp ce portarul eliberează mingea pentru a o pasa cu mâna, sare în fața lui ca să blocheze pasa, fără contact cu portarul. Imediat după aruncare, mingea ricoșează din capul atacantului și intră în poarta portarului. Care este decizia arbitrului?","correctText":"Gol anulat; LLI, cu CG numai dacă situația o impune."},{"id":367,"beforeQuestionRo":"La o lovitură de poartă, apărătorul alunecă și trimite accidental mingea spre propriul portar, care o prinde înaintea adversarului. Care este decizia arbitrului?","afterQuestionRo":"La executarea unei lovituri de poartă, un apărător încearcă să paseze unui mijlocaș apropiat, dar alunecă și trimite mingea doar câțiva metri. Un atacant advers intră în suprafața de pedeapsă și aleargă spre minge. Portarul plonjează și o prinde cu mâinile înainte ca atacantul să o controleze. Care este decizia arbitrului?","correctText":"Jocul continuă; mingea nu a fost trimisă deliberat portarului."},{"id":375,"beforeQuestionRo":"Portarul comite DOGSO printr-un fault în afara propriei suprafețe de pedeapsă. Arbitrul aplică avantajul, dar un apărător oprește deliberat cu mâna, în propria suprafață de pedeapsă, șutul care se îndreaptă spre poartă. Care este decizia arbitrului?","afterQuestionRo":"Portarul echipei A iese din propria suprafață de pedeapsă și faultează din neglijență un atacant al echipei B, împiedicându-i o ocazie clară de gol. Arbitrul aplică avantajul: un alt jucător al echipei B preia mingea și șutează spre poartă. În propria suprafață de pedeapsă, un apărător al echipei A își deplasează deliberat mâna sau brațul spre minge și o împiedică să intre în poartă. Care sunt deciziile arbitrului?","correctText":"LP, CG pentru portar și CR pentru apărătorul vinovat."},{"id":376,"beforeQuestionRo":"Un jucător deja avertizat oprește un atac promițător, apoi îndepărtează mingea înaintea procedurii disciplinare. Ce cartonașe arată arbitrul?","afterQuestionRo":"Un jucător avertizat în prima repriză pentru comportament nesportiv trage în repriza a doua tricoul unui adversar și oprește un atac promițător (SPA). Arbitrul fluieră și acordă lovitură liberă adversarilor. Înainte să înceapă procedura disciplinară, același jucător îndepărtează mingea cu piciorul pentru a împiedica executarea rapidă. Ce sancțiune disciplinară aplică arbitrul?","correctText":"Un CG pentru oprirea atacului, apoi CR; toate abaterile raportate."},{"id":377,"beforeQuestionRo":"Un jucător deja avertizat protestează evident prin gesturi după semnalizarea unui fault comis de el. Care este decizia arbitrului?","afterQuestionRo":"Cu mingea în joc, un jucător al echipei A împinge din neglijență un adversar al echipei B. Mingea iese apoi peste linia de margine, iar jucătorul A o ridică pentru a executa aruncarea. Oficialii indică însă LLD pentru B. Jucătorul A, deja avertizat în acest meci, aruncă furios mingea de pământ și gesticulează pentru a protesta. Care este decizia arbitrului?","correctText":"LLD pentru adversari; CG pentru protest, apoi CR pentru al doilea CG."},{"id":405,"beforeQuestionRo":"În propria suprafață de pedeapsă, brațul unui apărător mărește în mod nenatural suprafața corpului și împiedică intrarea mingii în poartă, fără ca abaterea prin jucarea mingii cu mâna să fie deliberat. Care este decizia arbitrului?","afterQuestionRo":"În propria suprafață de pedeapsă, un apărător atinge mingea cu mâna sau brațul și o împiedică să intre în propria poartă. Atingerea nu este deliberată, dar poziția mâinii sau a brațului îi mărește în mod nenatural suprafața corpului. Care este decizia arbitrului?","correctText":"LP și CG pentru împiedicarea înscrierii unui gol."},{"id":419,"beforeQuestionRo":"Un apărător execută o aruncare de la margine spre propriul portar. Un atacant urmărește mingea, dar portarul o prinde în propria suprafață de pedeapsă înaintea lui, putând împiedica o ocazie clară. Care este decizia arbitrului?","afterQuestionRo":"Un apărător execută o aruncare de la margine spre propriul portar. Mingea se îndreaptă spre poartă, iar un atacant advers aleargă să o intercepteze și are șanse să o controleze. Portarul, aflat mai aproape de propria linie de poartă decât oricare alt apărător, prinde mingea cu mâinile în propria suprafață de pedeapsă înaintea atacantului. Care este decizia arbitrului?","correctText":"LLI fără sancțiune disciplinară pentru portar."},{"id":437,"beforeQuestionRo":"Portarul eliberează mingea din mâini, apoi o prinde din nou în propria suprafață de pedeapsă înainte ca alt jucător să o atingă. Care este decizia arbitrului?","afterQuestionRo":"Cu mingea în joc, portarul o prinde în propria suprafață de pedeapsă, apoi o eliberează din mâini pe sol. Un atacant rămas pe teren în spatele său aleargă spre minge, fără să comită vreun fault. Portarul îl observă și prinde din nou mingea cu mâinile în propria suprafață de pedeapsă, înainte ca alt jucător să o atingă, împiedicând atacantul să o joace. Care este decizia arbitrului?","correctText":"LLI pentru echipa adversă și nicio sancțiune disciplinară."},{"id":439,"beforeQuestionRo":"Un atacant ține un apărător care protejează regulamentar mingea; după oprire, apărătorul îl lovește deliberat. Care este decizia arbitrului?","afterQuestionRo":"Un apărător protejează mingea aflată la distanță de joc, fără să folosească mâinile sau brațele pentru a ține adversarul. Atacantul care încearcă să câștige mingea îl ține pe apărător. După ce arbitrul oprește jocul, apărătorul îl lovește deliberat cu mâna pe atacant. Care este decizia arbitrului?","correctText":"LLD pentru apărători, CG posibil atacantului și CR apărătorului."},{"id":442,"beforeQuestionRo":"Un jucător comite DOGSO prin jucarea deliberată a mingii cu mâna. Care sunt reluarea jocului și sancțiunea disciplinară?","afterQuestionRo":"Un jucător împiedică o ocazie clară de gol a echipei adverse printr-o abatere deliberată de jucare a mingii cu mâna. Cum se stabilește reluarea în funcție de locul abaterii și ce sancțiune disciplinară se aplică?","correctText":"LLD sau LP în propria suprafață de pedeapsă și CR jucătorului pentru DOGSO."},{"id":450,"beforeQuestionRo":"Un apărător comite DOGSO printr-un fault. Piciorul atacantului se află în suprafața de pedeapsă, dar contactul are loc în afara acesteia. Care este decizia arbitrului?","afterQuestionRo":"Un apărător îl faultează pe un atacant și îi împiedică o ocazie clară de gol. Piciorul apărătorului intră în contact cu corpul atacantului în afara suprafeței de pedeapsă, deși un picior al atacantului se află deja în interiorul acesteia. Care este decizia arbitrului?","correctText":"LLD din punctul contactului și CR apărătorului pentru DOGSO."},{"id":453,"beforeQuestionRo":"Un apărător accidentat, aflat în spatele liniei porții, reintră fără permisiune și degajează din propria suprafață de pedeapsă mingea care intra în poartă. Care este decizia arbitrului?","afterQuestionRo":"Un apărător al echipei A a părăsit terenul pentru îngrijiri după o accidentare ușoară și se află încă în spatele liniei propriei porți. Un atacant al echipei B șutează pe lângă portarul echipei A, iar mingea se îndreaptă spre poarta acesteia. Apărătorul reintră fără permisiunea arbitrului și degajează mingea din propria suprafață de pedeapsă, împiedicând-o să intre în poartă. Care este decizia arbitrului?","correctText":"LP și CR pentru reintrare neautorizată și intervenție."},{"id":474,"beforeQuestionRo":"Arbitrul cere executarea unei lovituri libere la fluier, dar atacantul execută înaintea semnalului. Care este decizia arbitrului?","afterQuestionRo":"Echipa A primește o LLD în apropierea suprafeței de pedeapsă adverse. Arbitrul le cere clar atacanților să aștepte fluierul și se apropie de jucătorii echipei B pentru a asigura respectarea distanței regulamentare. În acel moment, un jucător al echipei A execută lovitura înaintea semnalului. Care este decizia arbitrului?","correctText":"Repetarea loviturii și CG executantului pentru comportament nesportiv."},{"id":482,"beforeQuestionRo":"Un atacant ține primul un apărător, iar acesta răspunde lovindu-l cu cotul și comite comportament violent. Care este decizia arbitrului?","afterQuestionRo":"Un atacant încearcă să câștige poziția față de un apărător care protejează mingea. Atacantul îl ține și îi împiedică deplasarea. Apărătorul încearcă să se elibereze și îl lovește apoi pe atacant cu cotul în față. Care este decizia arbitrului?","correctText":"LLD contra atacantului și CR apărătorului pentru comportament violent."},{"id":483,"beforeQuestionRo":"Un atacant blochează fără contact deplasarea unui apărător și oprește un atac promițător (SPA), când mingea nu este la distanță de joc. Care este decizia arbitrului?","afterQuestionRo":"Un apărător al echipei A pornește un contraatac promițător, trimite mingea înainte și încearcă să treacă de un atacant al echipei B. Acesta îi blochează deplasarea spre minge, fără contact fizic, când mingea nu este la distanță de joc pentru niciunul dintre ei. Mingea ajunge la un alt jucător al echipei B. Care este decizia arbitrului?","correctText":"LLI și CG pentru împiedicarea fără contact ce oprește un atac promițător (SPA)."},{"id":487,"beforeQuestionRo":"La o lovitură liberă, un apărător ține în suprafața de pedeapsă un atacant înainte ca mingea să ajungă la alt atacant aflat în ofsaid, care înscrie. Care este decizia tehnică?","afterQuestionRo":"La o lovitură liberă, mingea este trimisă în suprafața de pedeapsă adversă. Cât timp mingea este în aer, un apărător ține un atacant și îl împiedică să sară pentru a o juca. Mingea ajunge apoi la un alt atacant, aflat în poziție de ofsaid la executarea loviturii, care înscrie. Care este decizia tehnică a arbitrului?","correctText":"Gol anulat; LP acordată echipei în atac."},{"id":505,"beforeQuestionRo":"Un apărător comite un atac imprudent, apoi îndepărtează mingea pentru a întârzia executarea rapidă. Care este decizia arbitrului?","afterQuestionRo":"În timpul adăugat la finalul reprizei a doua, echipa A conduce cu un gol. Un apărător al echipei A îl atacă imprudent pe un adversar al echipei B. Înainte ca arbitrul să înceapă procedura disciplinară, un jucător B se pregătește să execute rapid lovitura liberă, dar același apărător A se apropie și îndepărtează mingea cu piciorul. Care este decizia arbitrului?","correctText":"LLD și două CG urmate de CR pentru eliminare."},{"id":508,"beforeQuestionRo":"Un apărător execută o LLD spre propriul portar, care alunecă și nu atinge mingea. Același apărător joacă din nou mingea și împiedică o ocazie clară de gol. Care este decizia arbitrului?","afterQuestionRo":"Un apărător execută o LLD spre propriul portar, care alunecă și nu atinge mingea. Un atacant advers aleargă spre aceasta. Înainte ca mingea să fie atinsă de alt jucător, apărătorul care a executat lovitura o șutează în afara terenului pentru o lovitură de colț, împiedicând astfel ocazia clară de gol a atacantului. Care este decizia arbitrului?","correctText":"LLI pentru atacanți și CR apărătorului pentru DOGSO."},{"id":515,"beforeQuestionRo":"Un apărător comite un fault care pune în pericol siguranța adversarului și primește CR. Un înlocuitor advers intră pe teren, dar este oprit înaintea confruntării. Care este decizia arbitrului?","afterQuestionRo":"Un apărător al echipei A comite lângă suprafața tehnică un fault care pune în pericol siguranța unui atacant al echipei B. Arbitrul oprește imediat jocul și elimină apărătorul. Un înlocuitor al echipei B intră atunci pe teren, dar coechipierii îl rețin pentru a evita confruntarea cu autorul faultului. Care este decizia arbitrului?","correctText":"Lovitura inițială pentru atacanți și CG pentru înlocuitor."},{"id":559,"beforeQuestionRo":"Un apărător joacă periculos cu piciorul la nivelul capului, fără contact, și împiedică o ocazie clară de gol. Care este decizia arbitrului?","afterQuestionRo":"Un atacant al echipei A, aflat la patru metri de poarta goală a echipei B, sare pentru a trimite mingea cu capul în poartă. Un apărător al echipei B ridică piciorul la nivelul capului adversarului și degajează mingea. Nu îl atinge, dar atacantul renunță să joace mingea de teama unei accidentări. Care este decizia arbitrului?","correctText":"LLI pentru echipa atacantă și CR apărătorului pentru DOGSO."},{"id":563,"beforeQuestionRo":"Un apărător protejează regulamentar mingea în propria suprafață de pedeapsă, apoi lovește cu cotul fața atacantului. Care este decizia arbitrului?","afterQuestionRo":"Un atacant al echipei A pătrunde cu mingea în suprafața de pedeapsă a echipei B. Un apărător al echipei B îl deposedează fără abatere. Apoi, în timp ce protejează mingea aflată la distanță de joc, își întinde brațele și îl lovește cu cotul în față pe atacant. Care este decizia arbitrului?","correctText":"LP pentru atacanți; CG dacă este imprudent sau CR dacă este violent."},{"id":574,"beforeQuestionRo":"Un jucător intră fără permisiune, interferează în propria suprafață de pedeapsă și împiedică o ocazie clară de gol. Care este decizia arbitrului?","afterQuestionRo":"Un jucător al echipei A intră pe teren fără permisiunea necesară a arbitrului. În propria suprafață de pedeapsă, intervine în joc sau asupra unui adversar al echipei B și împiedică astfel o ocazie clară de gol a echipei B. Cum se reia jocul și ce sancțiune disciplinară se aplică?","correctText":"LP pentru adversari și CR pentru jucător pentru DOGSO."},{"id":627,"beforeQuestionRo":"Echipa A execută rapid o lovitură liberă cu mingea în mișcare. Care este decizia arbitrului?","afterQuestionRo":"La mijlocul terenului, arbitrul acordă echipei A o lovitură liberă pentru ținerea unui jucător. Nu este necesară o sancțiune disciplinară și nici acordarea de îngrijiri medicale. Imediat după oprire, un jucător A execută rapid lovitura, deși mingea este încă în mișcare. Care este decizia arbitrului?","correctText":"Repetare pentru A sau avantaj dacă B beneficiază."},{"id":638,"beforeQuestionRo":"Un apărător comite DOGSO printr-un fault. Piciorul atacantului se află în suprafața de pedeapsă, dar contactul are loc în afara acesteia. Care este decizia arbitrului?","afterQuestionRo":"Un apărător îl faultează pe un atacant și îi împiedică o ocazie clară de gol. Piciorul apărătorului intră în contact cu corpul atacantului în afara suprafeței de pedeapsă, deși un picior al atacantului se află deja în interiorul acesteia. Care este decizia arbitrului?","correctText":"LLD din punctul contactului și CR apărătorului pentru DOGSO."},{"id":639,"beforeQuestionRo":"Mingea dintr-o lovitură liberă revine din bara transversală la executant, care o pasează unui coechipier ce înscrie. Care este decizia arbitrului?","afterQuestionRo":"Un jucător execută o lovitură liberă în apropierea suprafeței de pedeapsă adverse. Mingea lovește bara transversală și revine la executant fără să fi fost atinsă de alt jucător. Acesta o pasează unui coechipier, care înscrie. Care este decizia arbitrului?","correctText":"Gol anulat și LLI pentru echipa în apărare de la a doua atingere."},{"id":640,"beforeQuestionRo":"Arbitrul cere executarea unei lovituri libere la fluier, dar atacantul execută înaintea semnalului. Care este decizia arbitrului?","afterQuestionRo":"Echipa A primește o LLD în apropierea suprafeței de pedeapsă adverse. Arbitrul le cere clar atacanților să aștepte fluierul și se apropie de jucătorii echipei B pentru a asigura respectarea distanței regulamentare. În acel moment, un jucător al echipei A execută lovitura înaintea semnalului. Care este decizia arbitrului?","correctText":"Repetarea loviturii și CG executantului pentru comportament nesportiv."},{"id":643,"beforeQuestionRo":"Un apărător execută o LLD spre propriul portar, care alunecă și nu atinge mingea. Același apărător joacă din nou mingea și împiedică o ocazie clară de gol. Care este decizia arbitrului?","afterQuestionRo":"Un apărător execută o LLD spre propriul portar, care alunecă și nu atinge mingea. Un atacant advers aleargă spre aceasta. Înainte ca mingea să fie atinsă de alt jucător, apărătorul care a executat lovitura o șutează în afara terenului pentru o lovitură de colț, împiedicând astfel ocazia clară de gol a atacantului. Care este decizia arbitrului?","correctText":"LLI pentru atacanți și CR apărătorului pentru DOGSO."},{"id":668,"beforeQuestionRo":"Portarul comite DOGSO printr-un fault în afara propriei suprafețe de pedeapsă. Arbitrul aplică avantajul, dar un apărător oprește deliberat cu mâna, în propria suprafață de pedeapsă, șutul care se îndreaptă spre poartă. Care este decizia arbitrului?","afterQuestionRo":"Portarul echipei A iese din propria suprafață de pedeapsă și faultează din neglijență un atacant al echipei B, împiedicându-i o ocazie clară de gol. Arbitrul aplică avantajul: un alt jucător al echipei B preia mingea și șutează spre poartă. În propria suprafață de pedeapsă, un apărător al echipei A își deplasează deliberat mâna sau brațul spre minge și o împiedică să intre în poartă. Care sunt deciziile arbitrului?","correctText":"LP, CG pentru portar și CR pentru apărătorul vinovat."},{"id":686,"beforeQuestionRo":"În propria suprafață de pedeapsă, brațul unui apărător mărește în mod nenatural suprafața corpului și împiedică intrarea mingii în poartă, fără ca abaterea prin jucarea mingii cu mâna să fie deliberat. Care este decizia arbitrului?","afterQuestionRo":"În propria suprafață de pedeapsă, un apărător atinge mingea cu mâna sau brațul și o împiedică să intre în propria poartă. Atingerea nu este deliberată, dar poziția mâinii sau a brațului îi mărește în mod nenatural suprafața corpului. Care este decizia arbitrului?","correctText":"LP și CG pentru împiedicarea înscrierii unui gol."},{"id":697,"beforeQuestionRo":"Un jucător comite DOGSO prin jucarea deliberată a mingii cu mâna. Care sunt reluarea jocului și sancțiunea disciplinară?","afterQuestionRo":"Un jucător împiedică o ocazie clară de gol a echipei adverse printr-o abatere deliberată de jucare a mingii cu mâna. Cum se stabilește reluarea în funcție de locul abaterii și ce sancțiune disciplinară se aplică?","correctText":"LLD sau LP în propria suprafață de pedeapsă și CR jucătorului pentru DOGSO."},{"id":702,"beforeQuestionRo":"Un apărător accidentat, aflat în spatele liniei porții, reintră fără permisiune și degajează din propria suprafață de pedeapsă mingea care intra în poartă. Care este decizia arbitrului?","afterQuestionRo":"Un apărător al echipei A a părăsit terenul pentru îngrijiri după o accidentare ușoară și se află încă în spatele liniei propriei porți. Un atacant al echipei B șutează pe lângă portarul echipei A, iar mingea se îndreaptă spre poarta acesteia. Apărătorul reintră fără permisiunea arbitrului și degajează mingea din propria suprafață de pedeapsă, împiedicând-o să intre în poartă. Care este decizia arbitrului?","correctText":"LP și CR pentru reintrare neautorizată și intervenție."},{"id":717,"beforeQuestionRo":"La o lovitură liberă, un apărător ține în suprafața de pedeapsă un atacant înainte ca mingea să ajungă la alt atacant aflat în ofsaid, care înscrie. Care este decizia tehnică?","afterQuestionRo":"La o lovitură liberă, mingea este trimisă în suprafața de pedeapsă adversă. Cât timp mingea este în aer, un apărător ține un atacant și îl împiedică să sară pentru a o juca. Mingea ajunge apoi la un alt atacant, aflat în poziție de ofsaid la executarea loviturii, care înscrie. Care este decizia tehnică a arbitrului?","correctText":"Gol anulat; LP acordată echipei în atac."},{"id":592,"beforeQuestionRo":"Cu mingea în joc, un antrenor părăsește clar și în mod repetat limitele propriei suprafețe de pedeapsă tehnice, fără altă abatere. Ce sancțiune primește?","afterQuestionRo":"Cu mingea în joc, un antrenor părăsește în mod repetat limitele propriei suprafețe tehnice, fără să intre pe teren sau în suprafața tehnică adversă și fără altă abatere. Ce sancțiune primește pentru nerespectarea clară și repetată a acestor limite?","correctText":"CG pentru nerespectarea repetată a propriei suprafețe tehnice."}];
